import hashlib,json,os,subprocess
from pathlib import Path
node=None
processes=[]
def record(event):
 event['nodeid']=node
 path=Path(os.environ['UNITNAME_EVENT_DIR']);path.mkdir(exist_ok=True)
 with (path/(hashlib.sha256((node or 'session').encode()).hexdigest()[:20]+'.jsonl')).open('a') as stream:stream.write(json.dumps(event)+'\n')
def pytest_configure(config):
 from cbus_toolkit.cgate import CGateClient
 original=CGateClient.command
 def command(self,text,*args,**kwargs):
  try:result=original(self,text,*args,**kwargs)
  except BaseException as error:
   response=getattr(error,'response',None);record({'kind':'command','command':text,'exception':type(error).__name__,'code':getattr(response,'code',None),'lines':list(getattr(response,'lines',[])),'final':getattr(response,'final',str(error))});raise
  record({'kind':'command','command':text,'code':result.code,'lines':list(result.lines),'final':result.final});return result
 CGateClient.command=command
 original_popen=subprocess.Popen
 def popen(*args,**kwargs):
  process=original_popen(*args,**kwargs);argv=kwargs.get('args',args[0] if args else None)
  if isinstance(argv,list) and argv and argv[0]==os.environ['CBUS_CGATE_MOCK_BIN']:processes.append((process,argv));record({'kind':'mock-start','argv':argv,'pid':process.pid})
  return process
 subprocess.Popen=popen
def pytest_runtest_setup(item):
 global node
 node=item.nodeid
def pytest_runtest_logreport(report):
 if report.when=='call':record({'kind':'test-call','outcome':report.outcome})
def pytest_unconfigure(config):
 record({'kind':'mock-cleanup','processes':[{'argv':argv,'pid':process.pid,'exit':process.poll(),'terminal':process.poll() is not None} for process,argv in processes]})
